(2800, 'ielts', 'ielts', 'IELTS', NULL, 'Main', 'Normal', NULL, 1, NULL, NULL, '<h4 data-end=\"423\" data-start=\"361\"><span style=\"font-size:18px;\"><strong data-end=\"423\" data-start=\"366\">IELTS (International English Language Testing System)</strong></span></h4>\r\n\r\n<p data-end=\"958\" data-start=\"424\"><span style=\"font-size:18px;\"><strong data-end=\"440\" data-start=\"424\">Description:</strong><br data-end=\"443\" data-start=\"440\" />\r\nIELTS is a globally recognized exam that measures English proficiency for individuals whose first language is not English. It is jointly managed by the <strong data-end=\"614\" data-start=\"595\">British Council</strong>, <strong data-end=\"640\" data-start=\"616\">IDP: IELTS Australia</strong>, and <strong data-end=\"667\" data-start=\"646\">Cambridge English</strong>. The test is offered in <strong data-end=\"704\" data-start=\"692\">Academic</strong> and <strong data-end=\"729\" data-start=\"709\">General Training</strong> formats. Millions of candidates take IELTS yearly to demonstrate skills in <strong data-end=\"850\" data-start=\"805\">Listening, Reading, Writing, and Speaking</strong>. Scores range from <strong data-end=\"880\" data-start=\"870\">0 to 9</strong>, and results are accepted by over <strong data-end=\"957\" data-start=\"915\">10,000 organizations in 140+ countries</strong>.</span></p>\r\n\r\n<hr data-end=\"963\" data-start=\"960\" />\r\n<h3 data-end=\"991\" data-start=\"965\"><span style=\"font-size:18px;\"><strong data-end=\"991\" data-start=\"969\">Ways to Take IELTS</strong></span></h3>\r\n\r\n<h4 data-end=\"1033\" data-start=\"993\"><span style=\"font-size:18px;\"><strong data-end=\"1033\" data-start=\"998\">📝 Paper-based at a Test Centre</strong></span></h4>\r\n\r\n<ul data-end=\"1217\" data-start=\"1034\">\r\n	<li data-end=\"1054\" data-start=\"1034\">\r\n	<p data-end=\"1054\" data-start=\"1036\"><span style=\"font-size:18px;\"><strong data-end=\"1046\" data-start=\"1036\">Badge:</strong> Paper</span></p>\r\n	</li>\r\n	<li data-end=\"1217\" data-start=\"1055\">\r\n	<p data-end=\"1217\" data-start=\"1057\"><span style=\"font-size:18px;\"><strong data-end=\"1069\" data-start=\"1057\">Details:</strong> Listening, Reading, and Writing are completed on paper at a test centre using pen or pencil. Speaking is a face-to-face interview with an examiner.</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<h4 data-end=\"1262\" data-start=\"1219\"><span style=\"font-size:18px;\"><strong data-end=\"1262\" data-start=\"1224\">💻 Computer-based at a Test Centre</strong></span></h4>\r\n\r\n<ul data-end=\"1422\" data-start=\"1263\">\r\n	<li data-end=\"1286\" data-start=\"1263\">\r\n	<p data-end=\"1286\" data-start=\"1265\"><span style=\"font-size:18px;\"><strong data-end=\"1275\" data-start=\"1265\">Badge:</strong> Computer</span></p>\r\n	</li>\r\n	<li data-end=\"1422\" data-start=\"1287\">\r\n	<p data-end=\"1422\" data-start=\"1289\"><span style=\"font-size:18px;\"><strong data-end=\"1301\" data-start=\"1289\">Details:</strong> Listening, Reading, and Writing are taken on a computer at the centre. Speaking is conducted in person with an examiner.</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<h4 data-end=\"1448\" data-start=\"1424\"><span style=\"font-size:18px;\"><strong data-end=\"1448\" data-start=\"1429\">🌐 IELTS Online</strong></span></h4>\r\n\r\n<ul data-end=\"1654\" data-start=\"1449\">\r\n	<li data-end=\"1470\" data-start=\"1449\">\r\n	<p data-end=\"1470\" data-start=\"1451\"><span style=\"font-size:18px;\"><strong data-end=\"1461\" data-start=\"1451\">Badge:</strong> Online</span></p>\r\n	</li>\r\n	<li data-end=\"1654\" data-start=\"1471\">\r\n	<p data-end=\"1654\" data-start=\"1473\"><span style=\"font-size:18px;\"><strong data-end=\"1485\" data-start=\"1473\">Details:</strong> Academic IELTS can be taken online from home. Speaking is conducted via live video call with an examiner. The format, timing, and scoring match the test centre version.</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<hr data-end=\"1659\" data-start=\"1656\" />\r\n<h3 data-end=\"1697\" data-start=\"1661\"><span style=\"font-size:18px;\"><strong data-end=\"1697\" data-start=\"1665\">IELTS Band Score Scale (0–9)</strong></span></h3>\r\n\r\n<p data-end=\"1759\" data-start=\"1699\"><span style=\"font-size:18px;\">Each band level can be represented as a <strong data-end=\"1758\" data-start=\"1739\">responsive card</strong>:</span></p>\r\n\r\n<h4 data-end=\"1790\" data-start=\"1761\"><span style=\"font-size:18px;\"><strong data-end=\"1790\" data-start=\"1766\">Band 9 – Expert User</strong></span></h4>\r\n\r\n<ul data-end=\"1838\" data-start=\"1791\">\r\n	<li data-end=\"1838\" data-start=\"1791\">\r\n	<p data-end=\"1838\" data-start=\"1793\"><span style=\"font-size:18px;\">Fully accurate, fluent, and flexible English.</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<h4 data-end=\"1872\" data-start=\"1840\"><span style=\"font-size:18px;\"><strong data-end=\"1872\" data-start=\"1845\">Band 8 – Very Good User</strong></span></h4>\r\n\r\n<ul data-end=\"1934\" data-start=\"1873\">\r\n	<li data-end=\"1934\" data-start=\"1873\">\r\n	<p data-end=\"1934\" data-start=\"1875\"><span style=\"font-size:18px;\">Highly effective; occasional slips; handles complex detail.</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<h4 data-end=\"1963\" data-start=\"1936\"><span style=\"font-size:18px;\"><strong data-end=\"1963\" data-start=\"1941\">Band 7 – Good User</strong></span></h4>\r\n\r\n<ul data-end=\"2021\" data-start=\"1964\">\r\n	<li data-end=\"2021\" data-start=\"1964\">\r\n	<p data-end=\"2021\" data-start=\"1966\"><span style=\"font-size:18px;\">Operational command with some inaccuracies; copes well.</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<h4 data-end=\"2055\" data-start=\"2023\"><span style=\"font-size:18px;\"><strong data-end=\"2055\" data-start=\"2028\">Band 6 – Competent User</strong></span></h4>\r\n\r\n<ul data-end=\"2135\" data-start=\"2056\">\r\n	<li data-end=\"2135\" data-start=\"2056\">\r\n	<p data-end=\"2135\" data-start=\"2058\"><span style=\"font-size:18px;\">Generally effective despite errors; comfortable with fairly complex language.</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<h4 data-end=\"2166\" data-start=\"2137\"><span style=\"font-size:18px;\"><strong data-end=\"2166\" data-start=\"2142\">Band 5 – Modest User</strong></span></h4>\r\n\r\n<ul data-end=\"2233\" data-start=\"2167\">\r\n	<li data-end=\"2233\" data-start=\"2167\">\r\n	<p data-end=\"2233\" data-start=\"2169\"><span style=\"font-size:18px;\">Partial command; conveys overall meaning with frequent mistakes.</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<h4 data-end=\"2265\" data-start=\"2235\"><span style=\"font-size:18px;\"><strong data-end=\"2265\" data-start=\"2240\">Band 4 – Limited User</strong></span></h4>\r\n\r\n<ul data-end=\"2338\" data-start=\"2266\">\r\n	<li data-end=\"2338\" data-start=\"2266\">\r\n	<p data-end=\"2338\" data-start=\"2268\"><span style=\"font-size:18px;\">Basic competence in familiar situations; struggles with complex ideas.</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<h4 data-end=\"2375\" data-start=\"2340\"><span style=\"font-size:18px;\"><strong data-end=\"2375\" data-start=\"2345\">Band 3 – Extremely Limited</strong></span></h4>\r\n\r\n<ul data-end=\"2449\" data-start=\"2376\">\r\n	<li data-end=\"2449\" data-start=\"2376\">\r\n	<p data-end=\"2449\" data-start=\"2378\"><span style=\"font-size:18px;\">Communicates general meaning in familiar contexts; frequent breakdowns.</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<h4 data-end=\"2486\" data-start=\"2451\"><span style=\"font-size:18px;\"><strong data-end=\"2486\" data-start=\"2456\">Band 2 – Intermittent User</strong></span></h4>\r\n\r\n<ul data-end=\"2528\" data-start=\"2487\">\r\n	<li data-end=\"2528\" data-start=\"2487\">\r\n	<p data-end=\"2528\" data-start=\"2489\"><span style=\"font-size:18px;\">Great difficulty understanding English.</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<h4 data-end=\"2556\" data-start=\"2530\"><span style=\"font-size:18px;\"><strong data-end=\"2556\" data-start=\"2535\">Band 1 – Non-User</strong></span></h4>\r\n\r\n<ul data-end=\"2591\" data-start=\"2557\">\r\n	<li data-end=\"2591\" data-start=\"2557\">\r\n	<p data-end=\"2591\" data-start=\"2559\"><span style=\"font-size:18px;\">Can produce only isolated words.</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<h4 data-end=\"2626\" data-start=\"2593\"><span style=\"font-size:18px;\"><strong data-end=\"2626\" data-start=\"2598\">Band 0 – Did Not Attempt</strong></span></h4>\r\n\r\n<ul data-end=\"2655\" data-start=\"2627\">\r\n	<li data-end=\"2655\" data-start=\"2627\">\r\n	<p data-end=\"2655\" data-start=\"2629\"><span style=\"font-size:18px;\">No assessable information.</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<hr data-end=\"2660\" data-start=\"2657\" />\r\n<h3 data-end=\"2681\" data-start=\"2662\"><span style=\"font-size:18px;\"><strong data-end=\"2681\" data-start=\"2666\">Recognition</strong></span></h3>\r\n\r\n<p data-end=\"2778\" data-start=\"2682\"><span style=\"font-size:18px;\"><strong data-end=\"2691\" data-start=\"2682\">Note:</strong> IELTS results are accepted by over <strong data-end=\"2773\" data-start=\"2727\">10,000 organizations across 140+ countries</strong>. ✅</span></p>', NULL, 2754, NULL, NULL, NULL, '/uploads/banner_image/1717322634_1650004534_shutterstock_1887116167-1.jpg', NULL, NULL, NULL, NULL, 'ielts', NULL, '1', '0', NULL, NULL, NULL, '2024-04-11 06:21:49', '2025-08-25 18:13:57', NULL, NULL, NULL, NULL, NULL),
(2801, 'pte-language-test', 'ptelanguagetest', 'PTE', NULL, 'Main', 'Normal', NULL, 2, NULL, NULL, '<h3 data-end=\"328\" data-start=\"289\"><span style=\"font-size:16px;\"><strong data-end=\"326\" data-start=\"293\">PTE (Pearson Test of English)</strong></span></h3>\r\n\r\n<p data-end=\"703\" data-start=\"329\"><span style=\"font-size:16px;\"><strong data-end=\"345\" data-start=\"329\">📘 Overview:</strong><br data-end=\"348\" data-start=\"345\" />\r\nThe Pearson Test of English (Academic), commonly known as <strong data-end=\"413\" data-start=\"406\">PTE</strong>, assesses the English proficiency of individuals whose first language is not English. It evaluates fluency and comprehension across all critical domains: <strong data-end=\"613\" data-start=\"568\">Speaking, Writing, Reading, and Listening</strong>. This holistic approach ensures candidates are prepared for academic contexts globally.</span></p>\r\n\r\n<hr data-end=\"708\" data-start=\"705\" />\r\n<h3 data-end=\"745\" data-start=\"710\"><span style=\"font-size:16px;\"><strong data-end=\"743\" data-start=\"714\">🎯 Why Take the PTE Exam?</strong></span></h3>\r\n\r\n<ul data-end=\"1084\" data-start=\"746\">\r\n	<li data-end=\"853\" data-start=\"746\">\r\n	<p data-end=\"853\" data-start=\"748\"><span style=\"font-size:16px;\"><strong data-end=\"772\" data-start=\"748\">Computer-based Test:</strong> Convenient online assessment for non-native speakers planning to study abroad.</span></p>\r\n	</li>\r\n	<li data-end=\"966\" data-start=\"854\">\r\n	<p data-end=\"878\" data-start=\"856\"><span style=\"font-size:16px;\"><strong data-end=\"876\" data-start=\"856\">Skills Assessed:</strong></span></p>\r\n\r\n	<ul data-end=\"966\" data-start=\"881\">\r\n		<li data-end=\"901\" data-start=\"881\">\r\n		<p data-end=\"901\" data-start=\"883\"><span style=\"font-size:16px;\">🗣️ <strong data-end=\"899\" data-start=\"887\">Speaking</strong></span></p>\r\n		</li>\r\n		<li data-end=\"922\" data-start=\"904\">\r\n		<p data-end=\"922\" data-start=\"906\"><span style=\"font-size:16px;\">✍️ <strong data-end=\"920\" data-start=\"909\">Writing</strong></span></p>\r\n		</li>\r\n		<li data-end=\"943\" data-start=\"925\">\r\n		<p data-end=\"943\" data-start=\"927\"><span style=\"font-size:16px;\">📖 <strong data-end=\"941\" data-start=\"930\">Reading</strong></span></p>\r\n		</li>\r\n		<li data-end=\"966\" data-start=\"946\">\r\n		<p data-end=\"966\" data-start=\"948\"><span style=\"font-size:16px;\">🎧 <strong data-end=\"964\" data-start=\"951\">Listening</strong></span></p>\r\n		</li>\r\n	</ul>\r\n	</li>\r\n	<li data-end=\"1084\" data-start=\"967\">\r\n	<p data-end=\"1084\" data-start=\"969\"><span style=\"font-size:16px;\"><strong data-end=\"994\" data-start=\"969\">Integrated Questions:</strong> Some tasks evaluate two skills at once, like reading + speaking or listening + reading.</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<hr data-end=\"1089\" data-start=\"1086\" />\r\n<h3 data-end=\"1120\" data-start=\"1091\">&nbsp;</h3>\r\n\r\n<h3 data-end=\"329\" data-start=\"279\"><span style=\"font-size:16px;\"><strong data-end=\"329\" data-start=\"283\">📊 PTE Scoring Levels (Responsive Version)</strong></span></h3>\r\n\r\n<p data-end=\"433\" data-start=\"331\"><span style=\"font-size:16px;\">Instead of a traditional table, each score range can become a <strong data-end=\"401\" data-start=\"393\">card</strong> with the level and description:</span></p>\r\n\r\n<h4 data-end=\"454\" data-start=\"435\"><span style=\"font-size:16px;\"><strong data-end=\"452\" data-start=\"440\">Above 85</strong></span></h4>\r\n\r\n<p data-end=\"653\" data-start=\"455\"><span style=\"font-size:16px;\"><strong data-end=\"465\" data-start=\"455\">Level:</strong> Above 85<br data-end=\"477\" data-start=\"474\" />\r\n<strong data-end=\"493\" data-start=\"477\">Description:</strong> Can understand virtually everything heard or read. Able to summarize information from multiple sources coherently. Expresses thoughts fluently and precisely.</span></p>\r\n\r\n<hr data-end=\"658\" data-start=\"655\" />\r\n<h4 data-end=\"678\" data-start=\"660\"><span style=\"font-size:16px;\"><strong data-end=\"676\" data-start=\"665\">76 – 84</strong></span></h4>\r\n\r\n<p data-end=\"825\" data-start=\"679\"><span style=\"font-size:16px;\"><strong data-end=\"689\" data-start=\"679\">Level:</strong> 76 – 84<br data-end=\"700\" data-start=\"697\" />\r\n<strong data-end=\"716\" data-start=\"700\">Description:</strong> Understands demanding texts and implicit meanings. Expresses fluently and produces clear, structured text.</span></p>\r\n\r\n<hr data-end=\"830\" data-start=\"827\" />\r\n<h4 data-end=\"850\" data-start=\"832\"><span style=\"font-size:16px;\"><strong data-end=\"848\" data-start=\"837\">59 – 75</strong></span></h4>\r\n\r\n<p data-end=\"1044\" data-start=\"851\"><span style=\"font-size:16px;\"><strong data-end=\"861\" data-start=\"851\">Level:</strong> 59 – 75<br data-end=\"872\" data-start=\"869\" />\r\n<strong data-end=\"888\" data-start=\"872\">Description:</strong> Understands main ideas of complex texts, including technical topics. Interacts with native speakers fluently. Produces detailed text on various subjects.</span></p>\r\n\r\n<hr data-end=\"1049\" data-start=\"1046\" />\r\n<h4 data-end=\"1069\" data-start=\"1051\"><span style=\"font-size:16px;\"><strong data-end=\"1067\" data-start=\"1056\">51 – 58</strong></span></h4>\r\n\r\n<p data-end=\"1247\" data-start=\"1070\"><span style=\"font-size:16px;\"><strong data-end=\"1080\" data-start=\"1070\">Level:</strong> 51 – 58<br data-end=\"1091\" data-start=\"1088\" />\r\n<strong data-end=\"1107\" data-start=\"1091\">Description:</strong> Adequate command for familiar situations; may make mistakes. Handles standard spoken language and exchanges factual information reliably.</span></p>\r\n\r\n<hr data-end=\"1252\" data-start=\"1249\" />\r\n<h4 data-end=\"1272\" data-start=\"1254\"><span style=\"font-size:16px;\"><strong data-end=\"1270\" data-start=\"1259\">43 – 50</strong></span></h4>\r\n\r\n<p data-end=\"1426\" data-start=\"1273\"><span style=\"font-size:16px;\"><strong data-end=\"1283\" data-start=\"1273\">Level:</strong> 43 – 50<br data-end=\"1294\" data-start=\"1291\" />\r\n<strong data-end=\"1310\" data-start=\"1294\">Description:</strong> Understands main points on familiar topics. Produces simple connected text and describes experiences or opinions.</span></p>\r\n\r\n<hr data-end=\"1431\" data-start=\"1428\" />\r\n<h4 data-end=\"1451\" data-start=\"1433\"><span style=\"font-size:16px;\"><strong data-end=\"1449\" data-start=\"1438\">30 – 42</strong></span></h4>\r\n\r\n<p data-end=\"1604\" data-start=\"1452\"><span style=\"font-size:16px;\"><strong data-end=\"1462\" data-start=\"1452\">Level:</strong> 30 – 42<br data-end=\"1473\" data-start=\"1470\" />\r\n<strong data-end=\"1489\" data-start=\"1473\">Description:</strong> Understands sentences and common expressions. Communicates in routine tasks and describes immediate environment.</span></p>\r\n\r\n<hr data-end=\"1609\" data-start=\"1606\" />\r\n<h4 data-end=\"1629\" data-start=\"1611\"><span style=\"font-size:16px;\"><strong data-end=\"1627\" data-start=\"1616\">10 – 29</strong></span></h4>\r\n\r\n<p data-end=\"1819\" data-start=\"1630\"><span style=\"font-size:16px;\"><strong data-end=\"1640\" data-start=\"1630\">Level:</strong> 10 – 29<br data-end=\"1651\" data-start=\"1648\" />\r\n<strong data-end=\"1667\" data-start=\"1651\">Description:</strong> Understands and uses basic everyday expressions. Can introduce self and others, ask and answer simple questions, and interact slowly with assistance.</span></p>', NULL, 2754, NULL, NULL, NULL, '/uploads/banner_image/1756145427_download (7).png', NULL, NULL, NULL, NULL, 'pte-language-test', NULL, '1', '0', NULL, NULL, NULL, '2024-04-11 06:22:48', '2025-08-25 18:11:30', NULL, NULL, NULL, NULL, NULL),
(2802, 'video-gallery-one', 'videogalleryone', 'Video Gallery', NULL, 'Main', 'Video Gallery', NULL, 2, NULL, NULL, NULL, NULL, 2597, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'video-gallery-one', NULL, '1', '0', NULL, NULL, NULL, '2024-04-11 07:35:53', '2024-04-11 07:35:53', NULL, NULL, NULL, NULL, NULL),
(2808, 'Central-Oklahoma', 'centraloklahoma', 'University of Central Oklahoma', NULL, 'Main', 'Group', NULL, 1, 'City:New Work', NULL, 'Country:USA<br />\r\nProficiency Test:IELTS, PTE, TOEFL,SAT,ACT<br />\r\nDegree: Bachelor Degree, Master Degree,', NULL, 2751, NULL, NULL, NULL, '/uploads/banner_image/1717072841_376244992_696305595871493_1462585844275534673_n.jpg', NULL, NULL, NULL, NULL, 'Central-Oklahoma', NULL, '1', '0', NULL, NULL, NULL, '2024-04-15 15:50:03', '2024-05-30 18:43:37', NULL, NULL, NULL, NULL, NULL),
(2809, 'University-of-Central-Oklahoma-know-more', 'universityofcentraloklahomaknowmore', 'University of Central Oklahomahi Know More', NULL, 'Main', 'Normal', NULL, 1, 'University of Central Oklahoma is a public institution that was founded in 1890. It has a total undergraduate enrollment of 13,331, its setting is suburban, and the campus size is 210 acres. It utilizes a semester-based academic calendar. University of Central Oklahoma\'s ranking in the 2021 edition of Best Colleges is Regional Universities West, #68.', NULL, '<div style=\"text-align: justify;\">\r\n<h3 data-end=\"301\" data-start=\"239\">✈️ Aviation Degree at the University of Central Oklahoma</h3>\r\n\r\n<p data-end=\"696\" data-start=\"303\">The <strong data-end=\"347\" data-start=\"307\">University of Central Oklahoma (UCO)</strong>, established in 1890 and located in Edmond, Oklahoma, offers a strong academic environment with modern facilities and a commitment to student success. Among its many programs, the <strong data-end=\"547\" data-start=\"528\">Aviation degree</strong> is one of the most dynamic and career-oriented options, designed for students who aspire to build a future in the aviation and aerospace industry.</p>\r\n\r\n<h4 data-end=\"724\" data-start=\"698\">🌍 Program Overview</h4>\r\n\r\n<p data-end=\"1099\" data-start=\"725\">UCO’s <strong data-end=\"751\" data-start=\"731\">Aviation Program</strong> provides students with both academic knowledge and practical flight training. Students learn the fundamentals of aviation science, aircraft systems, aerodynamics, safety, and air traffic procedures. The program combines <strong data-end=\"1050\" data-start=\"972\">classroom instruction, simulation training, and hands-on flying experience</strong> in partnership with accredited flight schools.</p>\r\n\r\n<h4 data-end=\"1125\" data-start=\"1101\">🎓 Degree Options</h4>\r\n\r\n<p data-end=\"1172\" data-start=\"1126\">Students may pursue specializations such as:</p>\r\n\r\n<ul data-end=\"1474\" data-start=\"1173\">\r\n	<li data-end=\"1258\" data-start=\"1173\">\r\n	<p data-end=\"1258\" data-start=\"1175\"><strong data-end=\"1197\" data-start=\"1175\">Professional Pilot</strong> – preparing students to become licensed commercial pilots.</p>\r\n	</li>\r\n	<li data-end=\"1381\" data-start=\"1259\">\r\n	<p data-end=\"1381\" data-start=\"1261\"><strong data-end=\"1284\" data-start=\"1261\">Aviation Management</strong> – focusing on the business and operational side of airlines, airports, and aviation companies.</p>\r\n	</li>\r\n	<li data-end=\"1474\" data-start=\"1382\">\r\n	<p data-end=\"1474\" data-start=\"1384\"><strong data-end=\"1407\" data-start=\"1384\">Safety and Security</strong> – emphasizing aviation safety systems and regulatory compliance.</p>\r\n	</li>\r\n</ul>\r\n\r\n<h4 data-end=\"1506\" data-start=\"1476\">🛫 Career Opportunities</h4>\r\n\r\n<p data-end=\"1583\" data-start=\"1507\">Graduates of UCO’s Aviation program are well-prepared for careers such as:</p>\r\n\r\n<ul data-end=\"1745\" data-start=\"1584\">\r\n	<li data-end=\"1612\" data-start=\"1584\">\r\n	<p data-end=\"1612\" data-start=\"1586\">Commercial Airline Pilot</p>\r\n	</li>\r\n	<li data-end=\"1640\" data-start=\"1613\">\r\n	<p data-end=\"1640\" data-start=\"1615\">Corporate/Charter Pilot</p>\r\n	</li>\r\n	<li data-end=\"1662\" data-start=\"1641\">\r\n	<p data-end=\"1662\" data-start=\"1643\">Flight Instructor</p>\r\n	</li>\r\n	<li data-end=\"1682\" data-start=\"1663\">\r\n	<p data-end=\"1682\" data-start=\"1665\">Airport Manager</p>\r\n	</li>\r\n	<li data-end=\"1712\" data-start=\"1683\">\r\n	<p data-end=\"1712\" data-start=\"1685\">Aviation Safety Inspector</p>\r\n	</li>\r\n	<li data-end=\"1745\" data-start=\"1713\">\r\n	<p data-end=\"1745\" data-start=\"1715\">Air Traffic Management roles</p>\r\n	</li>\r\n</ul>\r\n\r\n<p data-end=\"1875\" data-start=\"1747\">With the growing demand for aviation professionals worldwide, UCO students gain a competitive edge in this high-growth sector.</p>\r\n\r\n<h4 data-end=\"1915\" data-start=\"1877\">📍 Why Choose UCO for Aviation?</h4>\r\n\r\n<ul data-end=\"2303\" data-start=\"1916\">\r\n	<li data-end=\"1994\" data-start=\"1916\">\r\n	<p data-end=\"1994\" data-start=\"1918\"><strong data-end=\"1939\" data-start=\"1918\">Modern Curriculum</strong> – semester-based courses aligned with FAA standards.</p>\r\n	</li>\r\n	<li data-end=\"2077\" data-start=\"1995\">\r\n	<p data-end=\"2077\" data-start=\"1997\"><strong data-end=\"2020\" data-start=\"1997\">Hands-On Experience</strong> – access to real-world flight training and simulators.</p>\r\n	</li>\r\n	<li data-end=\"2178\" data-start=\"2078\">\r\n	<p data-end=\"2178\" data-start=\"2080\"><strong data-end=\"2111\" data-start=\"2080\">Strong Industry Connections</strong> – networking opportunities with airlines and aviation companies.</p>\r\n	</li>\r\n	<li data-end=\"2303\" data-start=\"2179\">\r\n	<p data-end=\"2303\" data-start=\"2181\"><strong data-end=\"2216\" data-start=\"2181\">Supportive Learning Environment</strong> – a suburban campus spread across 210 acres, fostering academic and personal growth.</p>\r\n	</li>\r\n</ul>\r\n</div>', NULL, 2808, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'University-of-Central-Oklahoma-know-more', NULL, '1', '0', NULL, NULL, NULL, '2024-04-15 15:53:49', '2025-08-26 15:37:36', NULL, NULL, NULL, NULL, NULL),
(2825, 'why-uk', 'whyuk', 'Why Study in United Kingdom?', NULL, 'Main', 'Normal', NULL, 1, NULL, NULL, '<p data-end=\"412\" data-start=\"68\">The United Kingdom is one of the top destinations for international students pursuing higher education, offering world-class universities, outstanding teaching, and state-of-the-art facilities. With a strong emphasis on research and innovation, UK institutions provide an environment that nurtures academic excellence and professional growth.</p>\r\n\r\n<p data-end=\"810\" data-start=\"414\">According to global rankings, several of the world’s leading universities are located in the UK, reflecting the country’s commitment to high-quality education. Moreover, more than half of the research conducted by UK universities and colleges is recognized as <strong data-end=\"720\" data-start=\"674\">world-leading or internationally excellent</strong>, demonstrating the nation’s pivotal role in advancing knowledge across multiple fields.</p>\r\n\r\n<p data-end=\"1002\" data-start=\"812\">At <strong data-end=\"842\" data-start=\"815\">Education Air Hub Nepal</strong>, we guide aspiring students to explore these exceptional opportunities in the UK, helping them achieve their academic and career aspirations with confidence.</p>', NULL, 2796, NULL, NULL, NULL, '/uploads/banner_image/1713271956_R (1).jpeg', NULL, NULL, NULL, NULL, 'why-uk', NULL, '1', '0', NULL, NULL, NULL, '2024-04-16 12:52:37', '2025-08-25 05:34:26', NULL, NULL, NULL, NULL, NULL),
(2826, 'know-uk', 'knowuk', 'Know More Detail About United Kingdom', NULL, 'Main', 'Group', NULL, 2, NULL, NULL, NULL, NULL, 2796, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'know-uk', NULL, '1', '0', NULL, NULL, NULL, '2024-04-16 12:54:29', '2024-04-17 09:07:32', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `navigations` (`id`, `nav_name`, `alias`, `caption`, `caption_nepali`, `nav_category`, `page_type`, `page_template`, `position`, `short_content`, `short_content_nepali`, `long_content`, `long_content_nepali`, `parent_page_id`, `icon_image`, `featured_image`, `icon_image_caption`, `banner_image`, `link`, `main_attachment`, `attachment`, `page_title`, `page_keyword`, `page_description`, `page_status`, `nav_status`, `extra_one`, `extra_two`, `extra_three`, `created_at`, `updated_at`, `span`, `fb_link`, `insta_link`, `link_link`, `twit_link`) VALUES
(2827, 'uk-destiny', 'ukdestiny', 'United Kingdom Documentation', NULL, 'Main', 'Group', NULL, 3, 'show-index', NULL, '<div style=\"max-width:800px; margin:50px auto; font-family: \'Montserrat\', sans-serif; background:#fff; border-radius:15px; box-shadow:0 10px 30px rgba(0,0,0,0.1); padding:40px; border-top:5px solid #CF1312;\">\r\n<h2 style=\"text-align:center; color:#CF1312; font-size:2rem; margin-bottom:30px;\">Required Documents</h2>\r\n\r\n<div style=\"display:flex; flex-direction:column; gap:20px;\">\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">1</div>\r\n\r\n<div><strong>All academic documents</strong> up to your most recent degree</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">2</div>\r\n\r\n<div><strong>Valid Passport</strong></div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">3</div>\r\n\r\n<div><strong>IELTS / PTE / TOEFL</strong> Score</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">4</div>\r\n\r\n<div><strong>Statement of Purpose (SOP)</strong></div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">5</div>\r\n\r\n<div><strong>Marriage Certificate</strong> (if applicable for dependent)</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">6</div>\r\n\r\n<div><strong>Dependent Passport</strong> (if applicable)</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">7</div>\r\n\r\n<div><strong>Work Experience Certificate</strong> (if there is an educational gap)</div>\r\n</div>\r\n</div>\r\n</div>', NULL, 2796, NULL, NULL, NULL, '/uploads/banner_image/1713346751_R (1).jpeg', NULL, NULL, NULL, NULL, 'uk-destiny', NULL, '1', '0', NULL, NULL, NULL, '2024-04-16 12:55:05', '2025-08-25 05:46:59', NULL, NULL, NULL, NULL, NULL),
