(2845, 'Avila-University-know-more', 'avilauniversityknowmore', 'Avila University', NULL, 'Main', 'Normal', NULL, 1, 'Avila University is a catholic university providing liberal arts, professional, undergraduate, and graduate programs. It has quite a competitive admission policy with a less than 50% acceptance rate. Some popular majors offered by the university include Business Administration, Computer Science, Graphic Design, Marketing, Communication, MBA, etc', NULL, '<div style=\"text-align: justify;\"><strong>Bachelors&nbsp;Degree</strong><br />\r\nAvariety of Bachelor\'s degree programs in fields related to:&nbsp;\r\n<ol>\r\n	<li><strong>Bachelor of Arts in Arts Management</strong></li>\r\n	<li><strong>Bachelor of Fine Arts in Theatre Management</strong></li>\r\n	<li><strong>Bachelor of Arts in Arts Administration</strong></li>\r\n	<li><strong>Bachelor of Arts in Arts and Cultural Management&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Arts in Entertainment Management&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Arts in Arts Management&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Arts in Arts Management&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Arts in Arts Administration&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Fine Arts in Theatre Arts Management&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Arts in Arts Management&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Science in Arts Administration&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Arts in Arts and Media Management&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Fine Arts in Arts Management&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Science in Physics</strong></li>\r\n	<li><strong>Bachelor of Science in Information Technology</strong></li>\r\n	<li><strong>Bachelor of Science in Computer Science</strong></li>\r\n</ol>\r\n<br />\r\n<strong>Masters&nbsp;Degree</strong>\r\n\r\n<ol>\r\n	<li><strong>Master of Science in Computer Science&nbsp;</strong></li>\r\n	<li><strong>Doctor of Philosophy (Ph.D.) in Biology</strong>&nbsp;&nbsp;</li>\r\n	<li><strong>Master of Arts in Arts Management</strong>&nbsp;&nbsp;</li>\r\n	<li><strong>Master of Science in Chemical Engineering</strong>&nbsp;&nbsp;</li>\r\n	<li><strong>Master of Science in Mechanical Engineering&nbsp;</strong></li>\r\n	<li><strong>Master of Science in Electrical Engineering&nbsp;</strong></li>\r\n	<li><strong>Doctor of Philosophy (Ph.D.) in Physics&nbsp;</strong></li>\r\n	<li><strong>Master of Science in Information Technology&nbsp;</strong></li>\r\n	<li><strong>Master of Science in Environmental Science</strong>&nbsp;&nbsp;</li>\r\n	<li><strong>Master of Science in Data Science&nbsp;</strong><b>&nbsp;</b></li>\r\n	<li><strong>Master of Science in Environmental Engineering&nbsp;</strong></li>\r\n	<li><strong>Master of Science in Software Engineering&nbsp;</strong></li>\r\n	<li><strong>Master of Science in Robotics&nbsp;</strong></li>\r\n	<li><strong>Doctor of Philosophy (Ph.D.) in Mathematics</strong>&nbsp;</li>\r\n	<li><strong>Master of Science in Biotechnology</strong></li>\r\n	<li><strong>Doctor of Philosophy (Ph.D.) in Computer Science</strong></li>\r\n</ol>\r\n\r\n<div style=\"text-align: center;\"><br />\r\n<br />\r\n<span style=\"font-size:20px;\"><strong><span style=\"color:#000000;\">Intake</span></strong></span></div>\r\n\r\n<div style=\"text-align: center;\">&nbsp;</div>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" class=\"table\">\r\n	<thead>\r\n		<tr class=\"table-active\">\r\n			<th scope=\"col\">Intake&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</th>\r\n			<th scope=\"col\">Deadlines</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>Fall&nbsp;</td>\r\n			<td>&nbsp; &nbsp; -----</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Spring&nbsp;</td>\r\n			<td>&nbsp; &nbsp; -----</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n</div>', NULL, 2841, NULL, NULL, NULL, '/uploads/banner_image/1717077647_logo-one-line-no-tag.svg', NULL, NULL, NULL, NULL, 'Avila-University-know-more', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 07:01:11', '2024-05-30 22:39:10', NULL, NULL, NULL, NULL, NULL),
(2846, 'Bowling-Green-State-University-know-more', 'bowlinggreenstateuniversityknowmore', 'Bowling Green State University', NULL, 'Main', 'Normal', NULL, 1, 'Bowling Green State University is a public institution that was founded in 1910. It has a total undergraduate enrollment of 15,103, its setting is rural, and the campus size is 1,338 acres. It utilizes a semester-based academic calendar. Bowling Green State University\'s ranking in the 2021 edition of Best Colleges is National Universities, #258. Its in-state tuition and fees are $11,318; out-of-state tuition and fees are $19,305.', NULL, '<div style=\"text-align: justify;\">\r\n<div><strong>Bachelors&nbsp;Degree</strong><br />\r\nAvariety of Bachelor\'s degree programs in fields related to:&nbsp;\r\n<ol>\r\n	<li><strong>Bachelor of Arts in Arts Management</strong></li>\r\n	<li><strong>Bachelor of Fine Arts in Theatre Management</strong></li>\r\n	<li><strong>Bachelor of Arts in Arts Administration</strong></li>\r\n	<li><strong>Bachelor of Arts in Arts and Cultural Management&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Arts in Entertainment Management&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Arts in Arts Management&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Arts in Arts Management&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Arts in Arts Administration&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Arts in Arts and Media Management&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Fine Arts in Arts Management&nbsp;</strong></li>\r\n	<li><strong>Bachelor of Science in Physics</strong></li>\r\n	<li><strong>Bachelor of Science in Information Technology</strong></li>\r\n	<li><strong>Bachelor of Science in Computer Science</strong></li>\r\n</ol>\r\n<br />\r\n<strong>Masters&nbsp;Degree</strong>\r\n\r\n<ol>\r\n	<li><strong>Master of Science in Computer Science&nbsp;</strong></li>\r\n	<li><strong>Doctor of Philosophy (Ph.D.) in Biology</strong>&nbsp;&nbsp;</li>\r\n	<li><strong>Master of Arts in Arts Management</strong>&nbsp;&nbsp;</li>\r\n	<li><strong>Master of Science in Chemical Engineering</strong>&nbsp;&nbsp;</li>\r\n	<li><strong>Master of Science in Mechanical Engineering&nbsp;</strong></li>\r\n	<li><strong>Master of Science in Electrical Engineering&nbsp;</strong></li>\r\n	<li><strong>Doctor of Philosophy (Ph.D.) in Physics&nbsp;</strong></li>\r\n	<li><strong>Master of Science in Information Technology&nbsp;</strong></li>\r\n	<li><strong>Master of Science in Environmental Science</strong>&nbsp;&nbsp;<strong>&nbsp;</strong></li>\r\n	<li><strong>Master of Science in Software Engineering&nbsp;</strong></li>\r\n	<li><strong>Master of Science in Robotics&nbsp;</strong></li>\r\n	<li><strong>Doctor of Philosophy (Ph.D.) in Mathematics</strong>&nbsp;</li>\r\n	<li><strong>Master of Science in Biotechnology</strong></li>\r\n	<li><strong>Doctor of Philosophy (Ph.D.) in Computer Science</strong></li>\r\n</ol>\r\n</div>\r\n\r\n<div style=\"text-align: center;\"><br />\r\n<span style=\"font-size:20px;\"><strong><span style=\"color:#000000;\">Intake</span></strong></span></div>\r\n\r\n<div style=\"text-align: center;\">&nbsp;</div>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" class=\"table\">\r\n	<thead>\r\n		<tr class=\"table-active\">\r\n			<th scope=\"col\">Intake&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</th>\r\n			<th scope=\"col\">Deadlines</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>Fall&nbsp;</td>\r\n			<td>&nbsp; &nbsp; -----</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Spring&nbsp;</td>\r\n			<td>&nbsp; &nbsp; -----</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n</div>', NULL, 2842, NULL, NULL, NULL, '/uploads/banner_image/1717080114_bgsu-logo-wordmark-horiz-white.svg', NULL, NULL, NULL, NULL, 'Bowling-Green-State-University-know-more', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 07:22:35', '2024-05-30 22:40:04', NULL, NULL, NULL, NULL, NULL),
(2861, 'why-usa', 'whyusa', 'Why Study in U.S.A?', NULL, 'Main', 'Normal', NULL, 1, NULL, NULL, 'The USA continues to be one of the top destinations for international students pursuing higher education, renowned for its world-class universities and prestigious institutions. With over 4,500 acclaimed colleges and universities, the country offers unparalleled opportunities for students to acquire knowledge, develop skills, and build successful careers. Beyond academics, the USA remains a global leader in innovation, technology, business, and the arts. Home to the highest number of unicorn startups in the world, it also stands as one of the largest and most dynamic economies globally. At <strong data-end=\"826\" data-start=\"789\">Education Air Hub Nepal</strong>, we guide aspiring students to seize these exceptional opportunities and make their dream of studying in the USA a reality.', NULL, 2797, NULL, NULL, NULL, '/uploads/banner_image/1756096606_Untitled-designfs-1.png', NULL, NULL, NULL, NULL, 'why-usa', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 08:48:54', '2025-08-25 05:35:50', NULL, NULL, NULL, NULL, NULL),
(2862, 'know-usa-one', 'knowusaone', 'Know More Detail About USA', NULL, 'Main', 'Normal', NULL, 2, 'Here are detailed view about UAS and its processes to be followed :', NULL, NULL, NULL, 2797, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'know-usa-one', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 08:52:11', '2025-08-25 05:34:57', NULL, NULL, NULL, NULL, NULL),
(2863, 'usa-better-destiny', 'usabetterdestiny', 'USA Documentation', NULL, 'Main', 'Normal', NULL, 3, 'show-index', NULL, '<div style=\"max-width:800px; margin:50px auto; font-family: \'Montserrat\', sans-serif; background:#fff; border-radius:15px; box-shadow:0 10px 30px rgba(0,0,0,0.1); padding:40px; border-top:5px solid #CF1312;\">\r\n<h2 style=\"text-align:center; color:#CF1312; font-size:2rem; margin-bottom:30px;\">Required Documents</h2>\r\n\r\n<div style=\"display:flex; flex-direction:column; gap:20px;\">\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">1</div>\r\n\r\n<div><strong>All academic documents</strong> up to your most recent degree</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">2</div>\r\n\r\n<div><strong>Valid Passport</strong></div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">3</div>\r\n\r\n<div><strong>IELTS / PTE / TOEFL</strong> Score</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">4</div>\r\n\r\n<div><strong>Statement of Purpose (SOP)</strong></div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">5</div>\r\n\r\n<div><strong>Marriage Certificate</strong> (if applicable for dependent)</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">6</div>\r\n\r\n<div><strong>Dependent Passport</strong> (if applicable)</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">7</div>\r\n\r\n<div><strong>Work Experience Certificate</strong> (if there is an educational gap)</div>\r\n</div>\r\n</div>\r\n</div>', NULL, 2797, NULL, NULL, NULL, '/uploads/banner_image/1756099649_statue-of-liberty-silo-STATUE0216-26e12bb91d98492ea50cd9f6e180ef32.jpg', NULL, NULL, NULL, NULL, 'usa-better-destiny', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 08:53:43', '2025-08-25 05:27:29', NULL, NULL, NULL, NULL, NULL),
(2864, 'fre-ask-questio-one', 'freaskquestioone', 'Frequently Asked Questions', NULL, 'Main', 'Group', NULL, 4, NULL, NULL, NULL, NULL, 2797, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'fre-ask-questio-one', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 08:54:26', '2024-04-17 08:54:26', NULL, NULL, NULL, NULL, NULL),
(2865, 'usa-pop-uni', 'usapopuni', 'Popular Universities', NULL, 'Main', 'Photo Gallery', NULL, 5, NULL, NULL, NULL, NULL, 2797, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'usa-pop-uni', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 08:54:50', '2024-04-17 08:54:50', NULL, NULL, NULL, NULL, NULL),
(2871, 'earning-while-study-uk', 'earningwhilestudyuk', 'Earning While Studying in United Kingdom', NULL, 'Main', 'Normal', NULL, 1, 'In United Kingdom, international students can apply for permission to work. Student is permitted to work 20 hrs a week and full-time during vacations. But If you are studying masters or doctorate courses under subclass 574, then you are permitted to work unlimited hours a week.', NULL, NULL, NULL, 2826, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'earning-while-study-uk', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 09:09:03', '2024-04-17 09:09:12', NULL, NULL, NULL, NULL, NULL),
(2872, 'student-visa-uk', 'studentvisauk', 'Student Visa Processing', NULL, 'Main', 'Normal', NULL, 2, 'Student visa applicants from India, Nepal and Bhutan are required to undergo a Pre-Visa Assessment (PVA).', NULL, NULL, NULL, 2826, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'student-visa-uk', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 09:10:57', '2024-04-17 10:29:04', NULL, NULL, NULL, NULL, NULL),
(2873, 'process-time', 'processtime', 'Processing Times', NULL, 'Main', 'Normal', NULL, 3, 'Student applicants should lodge applications no more than 3 months and at least 8 weeks before course commencement dates. Some applications take longer to process. Students may be asked to undertake further medicals and some delays may be experienced due to the need to verify bank or education documents. Nepalese and Bhutanese applicants need to take into account the time taken for documents and letters to be sent and received by the Visa Office.<br />\r\nTo be granted a student visa you will need', NULL, NULL, NULL, 2826, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'process-time', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 09:11:49', '2024-04-17 09:11:49', NULL, NULL, NULL, NULL, NULL),
(2874, 'student-visa-processing-uk', 'studentvisaprocessinguk', 'Student Visa Process', NULL, 'Main', 'Normal', NULL, 4, 'Process to obtain UK Student Visa for international students<br />\r\nAny person who intends to undertake full-time study in a registered course in UK needs to obtain a UK Student Visa. A Student Visa permits the holder to travel to, enter and remain in Australia for the duration of the registered course of study. Overseas students cannot undertake part-time study in UK and must leave UK on completion of their course of study.', NULL, NULL, NULL, 2826, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'student-visa-processing-uk', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 09:13:05', '2024-04-17 10:28:56', NULL, NULL, NULL, NULL, NULL),
(2879, 'uk-one-fq', 'ukonefq', 'uk-one-fq', NULL, 'Main', 'Normal', NULL, 1, 'What are the reasons for UK Student Visa Refusals?&nbsp;', NULL, 'There are many causes for visa refusals, but these are a few of the most common:\r\n<ul>\r\n	<li>Failure to submit all necessary documentation with the visa application.</li>\r\n	<li>Providing false documentation or application information.</li>\r\n	<li>Failing to provide complete information about the course, university, study objective, or future career plan during the visa interview.</li>\r\n</ul>', NULL, 2828, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'uk-one-fq', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 09:28:09', '2024-05-30 22:07:23', NULL, NULL, NULL, NULL, NULL),
(2880, 'uk-two-fq', 'uktwofq', 'uk-two-fq', NULL, 'Main', 'Normal', NULL, 2, 'Why UK not other countries for study?', NULL, 'Students choose to study in the UK over other countries because of various reasons, including the quality of education, the reputation of UK universities, and the opportunity to immerse themselves in a different culture.', NULL, 2828, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'uk-two-fq', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 09:30:24', '2024-05-30 22:07:28', NULL, NULL, NULL, NULL, NULL),
(2889, 'usa-q-1', 'usaq1', 'usa-q-1', NULL, 'Main', 'Normal', NULL, 1, 'How much GPA is required to study in the USA?', NULL, 'Depending on the university and course of study, a minimum GPA of 2.5 to 3.0 on a 4.0 scale is usually required for acceptance to study in the United States.', NULL, 2864, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'usa-q-1', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 09:56:11', '2024-05-30 22:07:47', NULL, NULL, NULL, NULL, NULL),
(2890, 'usa-q-2', 'usaq2', 'usa-q-1', NULL, 'Main', 'Normal', NULL, 2, 'How much of a study gap is acceptable in the USA?', NULL, 'The US education system allows for one year of gap time, but if a student needs more than one year, they must give a valid reason with acceptable proof.', NULL, 2864, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'usa-q-2', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 09:56:39', '2025-08-25 04:37:38', NULL, NULL, NULL, NULL, NULL),
(2900, 'application-japan', 'applicationjapan', 'Application', NULL, 'Main', 'Normal', NULL, 6, 'Persons wishing to study in Japan should apply on form 157A and pay the current visa application charge.', NULL, NULL, NULL, 2826, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'application-japan', NULL, '1', '0', NULL, NULL, NULL, '2024-04-17 10:11:52', '2024-04-17 10:11:52', NULL, NULL, NULL, NULL, NULL),
(2904, 'enquiry', 'enquiry', 'Enquiry', NULL, 'Main', 'Normal', NULL, 11, NULL, NULL, 'country: USA,UK,Australia,Canada,Japan<br />\r\nfaculty: Under Graduate, Post Graduate<br />\r\neducationlevel: +2, Bachelor, Master<br />\r\nhaveyoudone: TOEFL-IBT, TOEFL, IELTS, SAT, GRE, GMAT, Language, SAT II', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'enquiry', NULL, '0', '0', NULL, NULL, NULL, '2024-04-17 15:27:06', '2025-08-20 16:43:17', NULL, NULL, NULL, NULL, NULL),
