(2912, 'study-home-usa', 'studyhomeusa', 'U.S.A', NULL, 'Home', 'Normal', NULL, 5, NULL, NULL, 'Why USA could be better destiny for your education.', NULL, 2907, NULL, NULL, '/abroad-study/usa', '/uploads/banner_image/1713525401_new-york-sunrise-chris-lord.jpg', NULL, NULL, NULL, NULL, 'study-home-usa', NULL, '1', '0', NULL, NULL, NULL, '2024-04-19 09:50:57', '2025-08-26 07:14:20', NULL, NULL, NULL, NULL, NULL),
(2940, 'about-us-two', 'aboutustwo', 'About Us', NULL, 'Main', 'Normal', NULL, 1, NULL, NULL, '<h2 data-end=\"335\" data-start=\"318\" style=\"text-align: justify;\"><span style=\"color:#0000CD;\">Introduction</span></h2>\r\n\r\n<p data-end=\"951\" data-start=\"336\" style=\"text-align: justify;\"><strong data-end=\"373\" data-start=\"336\">Education Air Hub Nepal Pvt. Ltd.</strong> is one of the leading institutions for students aspiring to build their careers in the aviation industry, both in Nepal and around the world. We are a team of professionals dedicated to providing outstanding support to deserving students who dream of excelling in aviation education. Our services cover comprehensive guidance, admission counseling, and career-oriented advice for training and higher studies in reputed aviation academies and universities across the globe, including the USA, Canada, UK, Ireland, Germany, Australia, Switzerland, Singapore, India, and beyond.</p>\r\n\r\n<p data-end=\"1537\" data-start=\"953\" style=\"text-align: justify;\">Our unwavering commitment to <strong data-end=\"1017\" data-start=\"982\">quality service and reliability</strong> has been the foundation of student success and professional growth in aviation for many years. We strongly believe that student satisfaction is the root of our progress, and we take pride in being recognized for excellence in all aspects of aviation education consulting. With a growing number of students successfully placed in internationally reputed flight schools, training centers, and universities, we have built a reputation as one of the most trusted aviation education and career solution providers in Nepal.</p>\r\n\r\n<p data-end=\"1920\" data-start=\"1539\" style=\"text-align: justify;\">Through our <strong data-end=\"1603\" data-start=\"1551\">strong global network and professional expertise</strong>, Education Air Hub Nepal has established a solid platform that connects students with top aviation institutes worldwide, helping them achieve their ambitions of becoming skilled professionals in fields such as piloting, cabin crew, aircraft maintenance engineering, air traffic control, and other aviation careers.</p>\r\n\r\n<hr data-end=\"1925\" data-start=\"1922\" />\r\n<h2 data-end=\"1942\" data-start=\"1927\" style=\"text-align: justify;\"><span style=\"color:#0000CD;\">Our Vision</span></h2>\r\n\r\n<p data-end=\"2199\" data-start=\"1943\" style=\"text-align: justify;\">At <strong data-end=\"1973\" data-start=\"1946\">Education Air Hub Nepal</strong>, we envision a future where every aspiring aviation professional has access to world-class education, resources, and opportunities to achieve their full potential and contribute meaningfully to the global aviation industry.</p>\r\n\r\n<h3 data-end=\"2234\" data-start=\"2201\" style=\"text-align: justify;\">Key Elements of Our Vision:</h3>\r\n\r\n<ul data-end=\"2961\" data-start=\"2235\">\r\n	<li data-end=\"2369\" data-start=\"2235\">\r\n	<p data-end=\"2369\" data-start=\"2237\" style=\"text-align: justify;\"><strong data-end=\"2280\" data-start=\"2237\">Empowerment Through Aviation Education:</strong> We empower students to pursue their aviation dreams with confidence and determination.</p>\r\n	</li>\r\n	<li data-end=\"2511\" data-start=\"2370\">\r\n	<p data-end=\"2511\" data-start=\"2372\" style=\"text-align: justify;\"><strong data-end=\"2398\" data-start=\"2372\">Personalized Guidance:</strong> Every student is unique; we provide tailored support addressing their strengths, career goals, and challenges.</p>\r\n	</li>\r\n	<li data-end=\"2686\" data-start=\"2512\">\r\n	<p data-end=\"2686\" data-start=\"2514\" style=\"text-align: justify;\"><strong data-end=\"2539\" data-start=\"2514\">Innovative Solutions:</strong> By incorporating the latest global aviation education standards and technology, we ensure students remain competitive in an ever-evolving field.</p>\r\n	</li>\r\n	<li data-end=\"2810\" data-start=\"2687\">\r\n	<p data-end=\"2810\" data-start=\"2689\" style=\"text-align: justify;\"><strong data-end=\"2711\" data-start=\"2689\">Lifelong Learning:</strong> Beyond training, we foster continuous growth in aviation knowledge and professional development.</p>\r\n	</li>\r\n	<li data-end=\"2961\" data-start=\"2811\">\r\n	<p data-end=\"2961\" data-start=\"2813\" style=\"text-align: justify;\"><strong data-end=\"2831\" data-start=\"2813\">Global Impact:</strong> Our mission is to produce highly competent aviation professionals who contribute to safety, innovation, and progress worldwide.</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr data-end=\"2966\" data-start=\"2963\" />\r\n<h2 data-end=\"2987\" data-start=\"2968\" style=\"text-align: justify;\"><span style=\"color:#0000CD;\">Our Commitment</span></h2>\r\n\r\n<p data-end=\"3322\" data-start=\"2988\" style=\"text-align: justify;\">We are committed to <strong data-end=\"3058\" data-start=\"3008\">transforming the aviation education experience</strong> for students and their families. By offering comprehensive services such as <strong data-end=\"3232\" data-start=\"3135\">career counseling, admission support, test preparation, and professional development programs</strong>, we ensure students receive the right guidance at every step of their aviation journey.</p>\r\n\r\n<p data-end=\"3683\" data-start=\"3324\" style=\"text-align: justify;\">At <strong data-end=\"3364\" data-start=\"3327\">Education Air Hub Nepal Pvt. Ltd.</strong>, we believe that aviation education is not just a career choice—it is a pathway to shaping the future of global connectivity and progress. We are passionate about guiding students towards their aviation dreams and equipping them with the skills and knowledge required to thrive in a dynamic and competitive industry.</p>\r\n\r\n<p data-end=\"3811\" data-start=\"3685\" style=\"text-align: justify;\"><strong data-end=\"3745\" data-start=\"3685\">Thank you for choosing Education Air Hub Nepal Pvt. Ltd.</strong> Together, let’s soar higher and achieve greatness in the skies.</p>', NULL, 2757, NULL, NULL, NULL, '/uploads/banner_image/1755793389_1.jpg', NULL, '1756050310_1755584882_WhatsApp Image 2025-08-19 at 11.06.51 AM.jpeg', NULL, NULL, 'about-us-two', NULL, '1', '0', NULL, NULL, NULL, '2024-04-19 17:07:13', '2025-08-24 15:45:10', NULL, NULL, NULL, NULL, NULL),
