(3026, 'test', 'test', 'teast', NULL, 'Main', 'Group', NULL, 1, NULL, NULL, NULL, NULL, 3025, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'test', NULL, '1', '0', NULL, NULL, NULL, '2025-08-24 11:02:58', '2025-08-24 11:02:58', NULL, NULL, NULL, NULL, NULL),
(3027, 'sdadasd', 'sdadasd', 'sddasd', NULL, 'Main', 'Normal', NULL, 1, 'sadasd', NULL, NULL, NULL, 3026, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'sdadasd', NULL, '1', '0', NULL, NULL, NULL, '2025-08-24 11:08:33', '2025-08-24 11:08:33', NULL, NULL, NULL, NULL, NULL),
(3028, 'Visa-Processing-details', 'visaprocessingdetails', 'Visa Processing', NULL, 'Main', 'Normal', NULL, 1, NULL, NULL, '<h3 data-end=\"239\" data-start=\"187\" style=\"text-align: justify;\">Visa Processing &amp; Guidance for Aspiring Pilots</h3>\r\n\r\n<p data-end=\"610\" data-start=\"241\" style=\"text-align: justify;\">At <strong data-end=\"271\" data-start=\"244\">Education Air Hub Nepal</strong>, we understand that securing a visa is one of the most crucial steps for students aspiring to pursue <strong data-end=\"416\" data-start=\"373\">pilot training or higher studies abroad</strong>. That is why we provide <strong data-end=\"478\" data-start=\"441\">comprehensive, end-to-end support</strong> throughout the entire visa application process, ensuring students can focus on their academic and aviation goals with confidence.</p>\r\n\r\n<p data-end=\"791\" data-start=\"612\" style=\"text-align: justify;\">Once a student secures admission from a <strong data-end=\"694\" data-start=\"652\">recognized aviation academy or college</strong>, our dedicated team assists in <strong data-end=\"777\" data-start=\"726\">preparing and verifying all necessary documents</strong>, including:</p>\r\n\r\n<ul data-end=\"1065\" data-start=\"793\">\r\n	<li data-end=\"885\" data-start=\"793\">\r\n	<p data-end=\"885\" data-start=\"795\" style=\"text-align: justify;\"><strong data-end=\"819\" data-start=\"795\">Financial statements</strong> to demonstrate the ability to cover tuition and living expenses</p>\r\n	</li>\r\n	<li data-end=\"942\" data-start=\"886\">\r\n	<p data-end=\"942\" data-start=\"888\" style=\"text-align: justify;\"><strong data-end=\"908\" data-start=\"888\">Academic records</strong> to meet university requirements</p>\r\n	</li>\r\n	<li data-end=\"1006\" data-start=\"943\">\r\n	<p data-end=\"1006\" data-start=\"945\" style=\"text-align: justify;\"><strong data-end=\"972\" data-start=\"945\">Medical fitness reports</strong> in line with aviation standards</p>\r\n	</li>\r\n	<li data-end=\"1065\" data-start=\"1007\">\r\n	<p data-end=\"1065\" data-start=\"1009\" style=\"text-align: justify;\"><strong data-end=\"1063\" data-start=\"1009\">Letters of acceptance and other official documents</strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p data-end=\"1273\" data-start=\"1067\" style=\"text-align: justify;\">Since visa procedures vary by country, our experts provide <strong data-end=\"1155\" data-start=\"1126\">country-specific guidance</strong>, helping students avoid common pitfalls, reduce confusion, and increase the likelihood of a successful application.</p>\r\n\r\n<p data-end=\"1543\" data-start=\"1275\" style=\"text-align: justify;\">For those pursuing careers in aviation—whether in <strong data-end=\"1412\" data-start=\"1325\">commercial pilot training, cabin crew, aviation management, or aircraft engineering</strong>—we offer <strong data-end=\"1445\" data-start=\"1422\">specialized support</strong> to address the unique documentation and requirements often needed in this field. This includes:</p>\r\n\r\n<ul data-end=\"1842\" data-start=\"1545\">\r\n	<li data-end=\"1608\" data-start=\"1545\">\r\n	<p data-end=\"1608\" data-start=\"1547\" style=\"text-align: justify;\"><strong data-end=\"1606\" data-start=\"1547\">ICAO-compliant medical certificates (Class 1 / Class 2)</strong></p>\r\n	</li>\r\n	<li data-end=\"1684\" data-start=\"1609\">\r\n	<p data-end=\"1684\" data-start=\"1611\" style=\"text-align: justify;\"><strong data-end=\"1644\" data-start=\"1611\">Proof of financial capability</strong> to cover training and living expenses</p>\r\n	</li>\r\n	<li data-end=\"1758\" data-start=\"1685\">\r\n	<p data-end=\"1758\" data-start=\"1687\" style=\"text-align: justify;\"><strong data-end=\"1742\" data-start=\"1687\">No-objection certificates or recommendation letters</strong> when required</p>\r\n	</li>\r\n	<li data-end=\"1842\" data-start=\"1759\">\r\n	<p data-end=\"1842\" data-start=\"1761\" style=\"text-align: justify;\"><strong data-end=\"1799\" data-start=\"1761\">Preparation for embassy interviews</strong>, including mock sessions and expert tips</p>\r\n	</li>\r\n</ul>\r\n\r\n<p data-end=\"2229\" data-start=\"1844\" style=\"text-align: justify;\">Our mission at <strong data-end=\"1886\" data-start=\"1859\">Education Air Hub Nepal</strong> is not just to assist students with their visa applications, but to ensure they are <strong data-end=\"2017\" data-start=\"1971\">fully prepared, confident, and stress-free</strong> throughout the process. With our guidance, aspiring pilots and aviation professionals can focus on their training and career development, while we handle the complex procedural details with expertise and care.</p>\r\n\r\n<p data-end=\"2055\" data-is-last-node=\"\" data-is-only-node=\"\" data-start=\"1845\" style=\"text-align: justify;\">&nbsp;</p>', NULL, 3010, NULL, NULL, NULL, '/uploads/banner_image/1756052803_Visa-Documentation-1-1024x636.jpg', NULL, '1756052803_visa-services.webp', NULL, NULL, 'Visa-Processing-details', NULL, '1', '0', NULL, NULL, NULL, '2025-08-24 16:26:43', '2025-08-24 16:50:13', NULL, NULL, NULL, NULL, NULL),
(3032, 'study-aus', 'studyaus', 'Study in Australia', NULL, 'Main', 'Group', NULL, 6, NULL, NULL, NULL, NULL, 2762, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'study-aus', NULL, '1', '0', NULL, NULL, NULL, '2025-08-25 06:00:58', '2025-08-25 06:00:58', NULL, NULL, NULL, NULL, NULL),
(3033, 'why-aus', 'whyaus', 'Why Study in Australia?', NULL, 'Main', 'Normal', NULL, 1, NULL, NULL, '<p data-end=\"507\" data-start=\"154\">Australia is a vibrant, safe, and multicultural nation with a strong economy and a world-class education system, making it an ideal destination for international students. As an English-speaking country, it offers a welcoming environment and over 22,000 courses across more than 1,100 institutions, including seven of the world’s top 100 universities.</p>\r\n\r\n<p data-end=\"838\" data-start=\"509\">The country hosts five of the world’s top 30 student cities, with excellent quality of life, affordability, and international scholarship opportunities. With a legacy of innovation, including breakthroughs like Wi-Fi, IVF, and the cervical cancer vaccine, Australia continues to inspire and shape global education and research.</p>', NULL, 3032, NULL, NULL, NULL, '/uploads/banner_image/1756102436_Places-to-Visit-in-Australia-1024x683.jpg', NULL, NULL, NULL, NULL, 'why-aus', NULL, '1', '0', NULL, NULL, NULL, '2025-08-25 06:02:50', '2025-08-25 06:14:13', NULL, NULL, NULL, NULL, NULL),
(3034, 'know-aus-details', 'knowausdetails', 'Know More Detail About Australia', NULL, 'Main', 'Normal', NULL, 2, NULL, NULL, NULL, NULL, 3032, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'know-aus-details', NULL, '1', '0', NULL, NULL, NULL, '2025-08-25 06:03:52', '2025-08-25 06:03:52', NULL, NULL, NULL, NULL, NULL),
(3035, 'aus-better-destiny', 'ausbetterdestiny', 'Australia Documentation', NULL, 'Main', 'Normal', NULL, 3, 'show-index', NULL, '<div style=\"max-width:800px; margin:50px auto; font-family: \'Montserrat\', sans-serif; background:#fff; border-radius:15px; box-shadow:0 10px 30px rgba(0,0,0,0.1); padding:40px; border-top:5px solid #CF1312;\">\r\n<h2 style=\"text-align:center; color:#CF1312; font-size:2rem; margin-bottom:30px;\">Required Documents</h2>\r\n\r\n<div style=\"display:flex; flex-direction:column; gap:20px;\">\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">1</div>\r\n\r\n<div><strong>All academic documents</strong> up to your most recent degree</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">2</div>\r\n\r\n<div><strong>Valid Passport</strong></div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">3</div>\r\n\r\n<div><strong>IELTS / PTE / TOEFL</strong> Score</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">4</div>\r\n\r\n<div><strong>Statement of Purpose (SOP)</strong></div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">5</div>\r\n\r\n<div><strong>Marriage Certificate</strong> (if applicable for dependent)</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">6</div>\r\n\r\n<div><strong>Dependent Passport</strong> (if applicable)</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">7</div>\r\n\r\n<div><strong>Work Experience Certificate</strong> (if there is an educational gap)</div>\r\n</div>\r\n</div>\r\n</div>', NULL, 3032, NULL, NULL, NULL, '/uploads/banner_image/1756102500_SxZrOZ6y8supLn7qTKX5pqAezmLuzfCs9XwCtzeP.jpg', NULL, NULL, NULL, NULL, 'aus-better-destiny', NULL, '1', '0', NULL, NULL, NULL, '2025-08-25 06:04:58', '2025-08-25 06:15:00', NULL, NULL, NULL, NULL, NULL),
(3036, 'fre-ask-questio-aus', 'freaskquestioaus', 'Frequently Asked Questions', NULL, 'Main', 'Group', NULL, 4, NULL, NULL, NULL, NULL, 3032, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'fre-ask-questio-aus', NULL, '1', '0', NULL, NULL, NULL, '2025-08-25 06:05:45', '2025-08-25 06:05:45', NULL, NULL, NULL, NULL, NULL),
(3037, 'aus-pop-uni', 'auspopuni', 'Popular Universities', NULL, 'Main', 'Photo Gallery', NULL, 5, NULL, NULL, NULL, NULL, 3032, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'aus-pop-uni', NULL, '1', '0', NULL, NULL, NULL, '2025-08-25 06:06:24', '2025-08-25 06:06:24', NULL, NULL, NULL, NULL, NULL),
(3038, 'usa-q-au', 'usaqau', 'usa-q-au', NULL, 'Main', 'Normal', NULL, 1, 'How much GPA is required to study in the USA?', NULL, 'Depending on the university and course of study, a minimum GPA of 2.5 to 3.0 on a 4.0 scale is usually required for acceptance to study in the United States.', NULL, 3036, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'usa-q-au', NULL, '1', '0', NULL, NULL, NULL, '2025-08-25 06:07:25', '2025-08-25 06:07:25', NULL, NULL, NULL, NULL, NULL),
(3039, 'fre-ask-questio-aus-one', 'freaskquestioausone', 'fre-ask-questio-aus-one', NULL, 'Main', 'Normal', NULL, 2, 'How much GPA is required to study in the USA?', NULL, 'Depending on the university and course of study, a minimum GPA of 2.5 to 3.0 on a 4.0 scale is usually required for acceptance to study in the United States.', NULL, 3036, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'fre-ask-questio-aus-one', NULL, '1', '0', NULL, NULL, NULL, '2025-08-25 06:08:12', '2025-08-25 06:08:12', NULL, NULL, NULL, NULL, NULL),
(3041, 'study-canada', 'studycanada', 'Study In Canada', NULL, 'Main', 'Group', NULL, 7, NULL, NULL, NULL, NULL, 2762, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'study-canada', NULL, '1', '0', NULL, NULL, NULL, '2025-08-25 06:47:10', '2025-08-25 06:47:10', NULL, NULL, NULL, NULL, NULL),
(3042, 'Why-Study-in-Canada', 'whystudyincanada', 'Why Study in Canada?', NULL, 'Main', 'Normal', NULL, 1, NULL, NULL, '<p data-end=\"353\" data-start=\"106\">Canada, with its vast landscapes and vibrant cities, perfectly blends natural beauty with urban sophistication. Known for safety, stability, and innovation, it welcomes students from around the world and celebrates a rich multicultural heritage.</p>\r\n\r\n<p data-end=\"587\" data-start=\"355\">As the second-largest country by land, Canada offers a spacious environment and a high quality of life. Its world-class universities, strong economy, and bilingual language programs make it a top choice for international students.</p>\r\n\r\n<p data-end=\"853\" data-start=\"589\">With over 200 languages spoken and a history of embracing millions of immigrants, Canada is inclusive, culturally diverse, and globally recognized for excellence in education, making it an ideal destination for students seeking academic and career opportunities.</p>', NULL, 3041, NULL, NULL, NULL, '/uploads/banner_image/1756104554_TAL-old-quebec-canada-CNTRY2RLOCT1124-10578d1df275402594f62494d6eeeac1.jpg', NULL, NULL, NULL, NULL, 'Why-Study-in-Canada', NULL, '1', '0', NULL, NULL, NULL, '2025-08-25 06:49:14', '2025-08-25 06:49:14', NULL, NULL, NULL, NULL, NULL),
(3044, 'Know-more-canada', 'knowmorecanada', 'Know More Detail About USA', NULL, 'Main', 'Normal', NULL, 2, NULL, NULL, NULL, NULL, 3041, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Know-more-canada', NULL, '1', '0', NULL, NULL, NULL, '2025-08-25 06:51:44', '2025-08-25 06:51:44', NULL, NULL, NULL, NULL, NULL),
(3045, 'canada-better-destiny', 'canadabetterdestiny', 'Canda Documentation', NULL, 'Main', 'Normal', NULL, 3, 'show-index', NULL, '<div style=\"max-width:800px; margin:50px auto; font-family: \'Montserrat\', sans-serif; background:#fff; border-radius:15px; box-shadow:0 10px 30px rgba(0,0,0,0.1); padding:40px; border-top:5px solid #CF1312;\">\r\n<h2 style=\"text-align:center; color:#CF1312; font-size:2rem; margin-bottom:30px;\">Required Documents</h2>\r\n\r\n<div style=\"display:flex; flex-direction:column; gap:20px;\">\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">1</div>\r\n\r\n<div><strong>All academic documents</strong> up to your most recent degree</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">2</div>\r\n\r\n<div><strong>Valid Passport</strong></div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">3</div>\r\n\r\n<div><strong>IELTS / PTE / TOEFL</strong> Score</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">4</div>\r\n\r\n<div><strong>Statement of Purpose (SOP)</strong></div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">5</div>\r\n\r\n<div><strong>Marriage Certificate</strong> (if applicable for dependent)</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">6</div>\r\n\r\n<div><strong>Dependent Passport</strong> (if applicable)</div>\r\n</div>\r\n\r\n<div style=\"display:flex; align-items:flex-start; gap:15px;\">\r\n<div style=\"min-width:35px; height:35px; background:#CF1312; border-radius:50%; color:#fff; text-align:center; line-height:35px; font-weight:bold;\">7</div>\r\n\r\n<div><strong>Work Experience Certificate</strong> (if there is an educational gap)</div>\r\n</div>\r\n</div>\r\n</div>', NULL, 3041, NULL, NULL, NULL, '/uploads/banner_image/1756104765_Niagara-Falls-Canada-Visitor-Visa-Guide-Canada-Immigration-and-Visa-Information-1024x576.jpg', NULL, NULL, NULL, NULL, 'canada-better-destiny', NULL, '1', '0', NULL, NULL, NULL, '2025-08-25 06:52:45', '2025-08-25 06:53:04', NULL, NULL, NULL, NULL, NULL),
