(3047, 'canada-q-1', 'canadaq1', 'canada-q-1', NULL, 'Main', 'Normal', NULL, 1, 'How much GPA is required to study in the Canada?', NULL, 'Depending on the university and course of study, a minimum GPA of 2.5 to 3.0 on a 4.0 scale is usually required for acceptance to study in the Canada.', NULL, 3046, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'canada-q-1', NULL, '1', '0', NULL, NULL, NULL, '2025-08-25 06:54:51', '2025-08-25 06:54:51', NULL, NULL, NULL, NULL, NULL),
(3048, 'fre-ask-questio-canada', 'freaskquestiocanada', 'Frequently Asked Questions', NULL, 'Main', 'Normal', NULL, 2, 'How much of a study gap is acceptable in the Canada?', NULL, 'The US education system allows for one year of gap time, but if a student needs more than one year, they must give a valid reason with acceptable proof.', NULL, 3046, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'fre-ask-questio-canada', NULL, '1', '0', NULL, NULL, NULL, '2025-08-25 06:55:49', '2025-08-25 06:55:49', NULL, NULL, NULL, NULL, NULL),
(3049, 'testi-three', 'testithree', 'Aditya Chaudhary', NULL, 'Home', 'Normal', NULL, 5, 'Student', NULL, '\"With Education Air Hub Nepal’s guidance, I am progressing confidently on my path to a pilot career. Their expertise makes everything easier!\"', NULL, 2472, NULL, NULL, NULL, '/uploads/banner_image/1756275474_829459_man_512x512.png', NULL, NULL, NULL, NULL, 'testi-three', NULL, '1', '0', NULL, NULL, NULL, '2025-08-27 06:14:33', '2025-08-27 06:17:54', NULL, NULL, NULL, NULL, NULL),
(3050, 'testi-four', 'testifour', 'Sonalika Dahal', NULL, 'Home', 'Normal', NULL, 6, 'Student', NULL, '\"Education Air Hub Nepal is guiding me toward my dream of becoming a pilot. Their support and advice make the journey clear and inspiring!\"', NULL, 2472, NULL, NULL, NULL, '/uploads/banner_image/1756275440_829459_man_512x512.png', NULL, NULL, NULL, NULL, 'testi-four', NULL, '1', '0', NULL, NULL, NULL, '2025-08-27 06:15:21', '2025-08-27 06:17:20', NULL, NULL, NULL, NULL, NULL),
